  public getSpec(code: string): ICurrencyPrecisionSpec | undefined {
    return this.currencies.get(code);
  }

  public formatAmount(code: string, amount: number): string {
    const spec = this.getSpec(code);
    const dec = spec ? spec.decimalPlaces : 2;
    return amount.toFixed(dec);
  }
